APX.cy = {"country":{"name":"Cyprus","tagline":"The island of Commandaria, the oldest named wine still made, and of phylloxera-free mountain vines.","classification":"Cyprus follows the EU system: seven PDOs (ΠΟΠ, OEOP on older labels) and four regional PGIs named after the districts (Lemesos, Pafos, Larnaka, Lefkosia). Commandaria's rules are among the strictest in Europe: only Xynisteri and Mavro from 14 named villages, goblet-trained and unirrigated vines at least four years old, harvest only when the Vine Products Commission gives the signal, grapes sun-dried (usually 7 to 10 days) to 390 to 450 grams of sugar per litre, and at least two years in oak. The six regional PDOs require vineyards above about 600 to 750 metres, low yields and minimum vine ages."},"regions":[{"name":"Troodos wine villages","slug":"troodos-wine-villages","tagline":"The 'wine villages' of the southern Troodos, from Commandaria to Pitsilia.","ids":["cy-commandaria","cy-krasochoria-lemesou","cy-krasochoria-lemesou-afames","cy-krasochoria-lemesou-laona","cy-laona-akama","cy-pitsilia","cy-vouni-panagias-ampelitis"]}],"items":{"cy-commandaria":{"name":"Commandaria","cat":"PDO","region":"Troodos wine villages","created":"1990 (national law); EU register","styles":["sweet","fortified"],"grapes":"Xynisteri and Mavro","summary":"Commandaria is a sweet amber wine made from sun-dried Xynisteri and Mavro grown in 14 villages on the southern slopes of the Troodos, north of Limassol: Agios Georgios, Agios Konstantinos, Agios Mamas, Agios Pavlos, Apsiou, Gerasa, Doros, Zoopigi, Kalo Chorio, Kapilio, Laneia, Louvaras, Monagri and Silikou. Grapes are picked very ripe, laid in the sun for about a week to raise sugar to 390 to 450 grams per litre, fermented until the yeast gives up around 15 percent alcohol (fortification is allowed but not required), and aged at least two years in oak. Good Commandaria tastes of raisin, fig, carob, coffee and orange peel with enough acidity to stay fresh, and old bottlings from the solera-like 'mana' tradition can be remarkable.\n\nThe name comes from the Grande Commanderie of the Knights Templar and Hospitaller at Kolossi, which exported the wine across medieval Europe, and it is the oldest wine name in continuous use. Production fell to around 200,000 bottles a year by 2025; UNESCO's inscription of its traditions in December 2025 is meant to help revive it.","terroir":"South-facing slopes of 500 to 900 metres; calcareous and volcanic soils; goblet-trained, unirrigated vines at least four years old.","producers":["KEO","ETKO","SODAP","LOEL","Kyperounda","Tsiakkas","Revecca","Aes Ambelis","Ayia Mavri"],"nerd_note":"Many old Commandaria lots were kept in a 'mana' (mother) jar, topped up with each new vintage like a solera, so a single jar could hold wine generations old.","rslug":"troodos-wine-villages"},"cy-krasochoria-lemesou":{"name":"Krasochoria Lemesou","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white","rose"],"grapes":"Xynisteri, Maratheftiko, Mavro, Yiannoudi, Promara and international varieties","summary":"The 'wine villages of Limassol' PDO covers the high villages west of the Commandaria zone, around Omodos, Vasa, Koilani, Malia and Arsos, the historic heart of Cypriot table wine. Limestone and chalk soils at 600 to 1,200 metres give fresh Xynisteri and structured Maratheftiko.","producers":["Vasilikon","Zambartas","Ktima Gerolemo","Vlassides"],"rslug":"troodos-wine-villages"},"cy-krasochoria-lemesou-afames":{"name":"Krasochoria Lemesou-Afames","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white"],"grapes":"Xynisteri, Maratheftiko, Mavro and others","summary":"A sub-zone of the Limassol wine villages named after the Afames hill above Pelendri and Kato Platres, on the higher, volcanic eastern side of the zone. Higher and cooler than most of the Limassol wine villages, it is planted with Xynisteri, Maratheftiko and Mavro alongside international grapes.","rslug":"troodos-wine-villages"},"cy-krasochoria-lemesou-laona":{"name":"Krasochoria Lemesou-Laona","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white"],"grapes":"Xynisteri, Maratheftiko, Mavro and others","summary":"A sub-zone of the Limassol wine villages around the Laona area near Arsos and Omodos, on limestone at 900 to 1,200 metres. The limestone gives fresh, saline Xynisteri, and Maratheftiko and Yiannoudi give the zone's best reds.","rslug":"troodos-wine-villages"},"cy-laona-akama":{"name":"Laona Akama","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white"],"grapes":"Xynisteri, Maratheftiko, Mavro, Yiannoudi and others","summary":"The limestone Laona plateau above the Akamas peninsula in the north-west, around Kathikas and Kritou Terra, between 450 and 750 metres; sea breezes give some of the island's most saline whites.","producers":["Sterna","Vasa","Tsangarides"],"rslug":"troodos-wine-villages"},"cy-pitsilia":{"name":"Pitsilia","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white"],"grapes":"Xynisteri, Maratheftiko, Mavro, Cabernet Sauvignon and others","summary":"The high Pitsilia area on the eastern Troodos (around Kyperounda, Agros and Pelendri) has some of Europe's highest vineyards, up to around 1,500 metres, on igneous soils. Kyperounda's winery at about 1,450 metres is among the highest in Europe.","producers":["Kyperounda","Tsiakkas","Agia Mavri"],"rslug":"troodos-wine-villages"},"cy-vouni-panagias-ampelitis":{"name":"Vouni Panagias-Ambelitis","cat":"PDO","region":"Troodos wine villages","created":"2006","styles":["red","white"],"grapes":"Xynisteri, Maratheftiko, Mavro and others","summary":"A cool plateau around Panagia in the Paphos hills at 800 to 1,100 metres, the source of fresh Xynisteri and of Maratheftiko from Vouni Panagia winery. The plateau is among the coolest places to grow grapes in Cyprus, and the zone's bush vines are ungrafted, like all Cypriot vines.","producers":["Vouni Panayia","Kolios"],"rslug":"troodos-wine-villages"}}};
